package com.example.ayni.emergency.controller;import com.example.ayni.emergency.dto.LocationRequest;import com.example.ayni.emergency.model.*;import com.example.ayni.emergency.service.EmergencyService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/emergency")public class EmergencyController{private final EmergencyService service;public EmergencyController(EmergencyService service){this.service=service;}@GetMapping("/alerts")public List<EmergencyAlert>alerts(){return service.alerts();}@GetMapping("/points")public List<EmergencyPoint>points(){return service.points();}@PutMapping("/location")@ResponseStatus(HttpStatus.NO_CONTENT)public void location(@AuthenticationPrincipal Jwt j,@Valid @RequestBody LocationRequest r){service.update(UUID.fromString(j.getSubject()),r);}}
